// Generated by an AI assistant. Run from week3 with: node eval/build_submission_reports.js
// Rebuilds the English baseline, stage comparison, analytics, and verification reports.

const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const vm = require('node:vm');

const OVERLAP_THRESHOLD = 5;
const MIN_USER_SUPPORT = 3;
const MIN_ITEM_SUPPORT = 3;
const ACTIVE_USER = 1;

(async function main() {
    const week3Dir = path.resolve(__dirname, '..');
    const week2Dir = path.resolve(week3Dir, '../week2/fixed');
    const fixedDir = path.join(week3Dir, 'fixed');
    const resultsDir = path.join(week3Dir, 'results');
    await fs.mkdir(resultsDir, { recursive: true });

    const [itemBuffer, ratingsText] = await Promise.all([
        fs.readFile(path.join(fixedDir, 'u.item')),
        fs.readFile(path.join(fixedDir, 'u.data'), 'utf8')
    ]);
    const decodedItemText = new TextDecoder('iso-8859-1').decode(itemBuffer);
    const data = parseDataset(ratingsText, decodedItemText);
    const incorrectlyDecoded = new TextDecoder('utf-8').decode(itemBuffer);
    data.legacyUtf8Title = incorrectlyDecoded.split(/\r?\n/)
        .find(line => line.startsWith('543|')).split('|')[1];
    const overlap = computeOverlapStats(data.movieRaters, data.numUsers);
    const similarityData = computeSimilarityMatrices(data);
    const userStages = computeUserStages(data, similarityData);
    const itemStages = computeItemStages(data, similarityData);
    const genreResults = await runWeek2Genre(week2Dir, ACTIVE_USER);
    const actualCf = await Promise.all([1, 196].map(userId => runWeek3Cf(fixedDir, userId)));

    for (const userId of [1, 196]) {
        const predicted = userStages.weightedSupport3After.topByUser[userId];
        const actualUser = actualCf.find(result => result.userId === userId);
        assertRecommendationsMatch(predicted, actualUser.userBasedTop5, `User-Based user ${userId}`);
        assertRecommendationsMatch(
            itemStages.topByUser.weightedSupport3After[userId],
            actualUser.itemBasedTop5,
            `Item-Based user ${userId}`
        );
    }
    assertItemBasedRegressionListsUnchanged(actualCf);

    assert.equal(data.titles[543], 'Misérables, Les (1995)');
    assert.equal(data.replacementTitleCount, 0);
    assert.deepEqual(genreResults.toyStoryGenres, ['Animation', "Children's", 'Comedy']);
    assert.equal(data.duplicateGroups.length, 18);
    assert.equal(data.duplicateAliasCases, 655);
    assert.equal(userStages.weightedSupport3After.duplicateRecommendations, 0);
    assert.equal(itemStages.weightedSupport3AfterDuplicateFix, 0);
    assert.equal(userStages.weightedSupport3After.emptyLists, 0);
    assert.equal(itemStages.emptyFinalLists, 0);

    const manual = computeManualCalculation(data, userStages);
    assert.ok(Math.abs(manual.codeSimilarity - manual.manualSimilarity) < 1e-12);
    assert.ok(Math.abs(manual.codePrediction - manual.manualPrediction) < 1e-12);

    const reports = {
        baseline: renderBaseline(data, overlap, userStages, itemStages),
        stages: renderStages(data, userStages, itemStages),
        analytics: renderAnalytics(data, overlap, genreResults, actualCf.find(result => result.userId === 1)),
        checks: renderChecks(data, genreResults, manual, userStages, itemStages)
    };

    await Promise.all([
        fs.writeFile(path.join(resultsDir, 'before_fixes.md'), reports.baseline),
        fs.writeFile(path.join(resultsDir, 'stage_comparison.md'), reports.stages),
        fs.writeFile(path.join(resultsDir, 'analytics.md'), reports.analytics),
        fs.writeFile(path.join(resultsDir, 'checks.md'), reports.checks)
    ]);
    console.log('Generated results/before_fixes.md, stage_comparison.md, analytics.md, and checks.md.');
})().catch(error => {
    console.error(error);
    process.exitCode = 1;
});

function parseDataset(ratingsText, itemText) {
    const ratings = ratingsText.trim().split(/\r?\n/).map(line => {
        const [userId, itemId, rating, timestamp] = line.split('\t').map(Number);
        return { userId, itemId, rating, timestamp };
    });
    const itemRows = itemText.trimEnd().split(/\r?\n/).map(line => line.split('|'));
    const numUsers = Math.max(...ratings.map(rating => rating.userId));
    const numMovies = Math.max(...itemRows.map(fields => Number(fields[0])));
    const titles = Array(numMovies + 1).fill('');
    const genresById = Array(numMovies + 1).fill(null);
    const users = Array.from({ length: numUsers + 1 }, () => []);
    const movieRaters = Array.from({ length: numMovies + 1 }, () => []);
    const ratingsMatrix = Array.from(
        { length: numUsers + 1 },
        () => new Float64Array(numMovies + 1)
    );

    const genreNames = [
        'Action', 'Adventure', 'Animation', "Children's", 'Comedy', 'Crime',
        'Documentary', 'Drama', 'Fantasy', 'Film-Noir', 'Horror', 'Musical',
        'Mystery', 'Romance', 'Sci-Fi', 'Thriller', 'War', 'Western'
    ];
    for (const fields of itemRows) {
        const movieId = Number(fields[0]);
        titles[movieId] = fields[1];
        genresById[movieId] = genreNames.filter((_, index) => Number(fields[index + 6]) === 1);
    }
    const toyStoryFields = itemRows.find(fields => Number(fields[0]) === 1);
    const legacyToyStoryGenres = genreNames.filter((_, index) => Number(toyStoryFields[index + 5]) === 1);
    for (const rating of ratings) {
        users[rating.userId].push(rating);
        movieRaters[rating.itemId].push(rating.userId);
        ratingsMatrix[rating.userId][rating.itemId] = rating.rating;
    }
    for (const raters of movieRaters) raters.sort((a, b) => a - b);

    const replacementTitleCount = titles.filter(title => title.includes('\uFFFD')).length;
    const duplicateGroupsMap = new Map();
    for (let movieId = 1; movieId <= numMovies; movieId++) {
        const key = titleKey(titles[movieId]);
        if (!duplicateGroupsMap.has(key)) duplicateGroupsMap.set(key, []);
        duplicateGroupsMap.get(key).push(movieId);
    }
    const duplicateGroups = [...duplicateGroupsMap.entries()]
        .filter(([, ids]) => ids.length > 1)
        .map(([key, ids]) => ({ key, ids }));

    let duplicateAliasCases = 0;
    for (let userId = 1; userId <= numUsers; userId++) {
        for (const group of duplicateGroups) {
            const ratedCount = group.ids.reduce(
                (count, movieId) => count + (ratingsMatrix[userId][movieId] !== 0 ? 1 : 0), 0
            );
            if (ratedCount > 0 && ratedCount < group.ids.length) duplicateAliasCases++;
        }
    }

    return {
        ratings,
        users,
        titles,
        genresById,
        legacyToyStoryGenres,
        movieRaters,
        ratingsMatrix,
        numUsers,
        numMovies,
        duplicateGroups,
        duplicateAliasCases,
        replacementTitleCount,
        movieCells: numUsers * numMovies
    };
}

function computeOverlapStats(movieRaters, numUsers) {
    const stride = numUsers + 1;
    const commonCounts = new Uint16Array(stride * stride);
    for (let movieId = 1; movieId < movieRaters.length; movieId++) {
        const raters = movieRaters[movieId];
        for (let left = 0; left < raters.length; left++) {
            for (let right = left + 1; right < raters.length; right++) {
                commonCounts[raters[left] * stride + raters[right]]++;
            }
        }
    }

    const pairs = [];
    for (let userA = 1; userA <= numUsers; userA++) {
        for (let userB = userA + 1; userB <= numUsers; userB++) {
            pairs.push(commonCounts[userA * stride + userB]);
        }
    }
    pairs.sort((a, b) => a - b);
    const atMostTwo = pairs.filter(count => count <= 2).length;
    const middle = Math.floor(pairs.length / 2);
    return {
        pairs: pairs.length,
        median: pairs.length % 2 ? pairs[middle] : (pairs[middle - 1] + pairs[middle]) / 2,
        atMostTwo,
        atMostTwoPercent: atMostTwo / pairs.length * 100,
        noCommon: pairs.filter(count => count === 0).length,
        mean: pairs.reduce((sum, count) => sum + count, 0) / pairs.length
    };
}

function computeSimilarityMatrices(data) {
    const { numUsers, numMovies, ratingsMatrix, movieRaters } = data;
    const userStride = numUsers + 1;
    const itemStride = numMovies + 1;
    const userCommon = new Uint16Array(userStride * userStride);
    const userRaw = new Float64Array(userStride * userStride);
    const userWeighted = new Float64Array(userStride * userStride);
    const userRatedMovies = Array.from({ length: userStride }, () => []);
    const itemRaw = new Float64Array(itemStride * itemStride);
    const itemWeighted = new Float64Array(itemStride * itemStride);

    for (let userId = 1; userId <= numUsers; userId++) {
        for (let movieId = 1; movieId <= numMovies; movieId++) {
            if (ratingsMatrix[userId][movieId] !== 0) userRatedMovies[userId].push(movieId);
        }
    }

    for (let userA = 1; userA <= numUsers; userA++) {
        const ratedA = userRatedMovies[userA];
        for (let userB = userA + 1; userB <= numUsers; userB++) {
            const ratedB = userRatedMovies[userB];
            let left = 0;
            let right = 0;
            let dot = 0;
            let normA = 0;
            let normB = 0;
            let count = 0;
            while (left < ratedA.length && right < ratedB.length) {
                const movieA = ratedA[left];
                const movieB = ratedB[right];
                if (movieA === movieB) {
                    const ratingA = ratingsMatrix[userA][movieA];
                    const ratingB = ratingsMatrix[userB][movieB];
                    dot += ratingA * ratingB;
                    normA += ratingA ** 2;
                    normB += ratingB ** 2;
                    count++;
                    left++;
                    right++;
                } else if (movieA < movieB) {
                    left++;
                } else {
                    right++;
                }
            }
            const raw = cosine(dot, normA, normB);
            const weighted = raw * Math.min(count / OVERLAP_THRESHOLD, 1);
            const ab = userA * userStride + userB;
            const ba = userB * userStride + userA;
            userCommon[ab] = count;
            userCommon[ba] = count;
            userRaw[ab] = userRaw[ba] = raw;
            userWeighted[ab] = userWeighted[ba] = weighted;
        }
    }

    for (let movieA = 1; movieA <= numMovies; movieA++) {
        const ratersA = movieRaters[movieA];
        for (let movieB = movieA + 1; movieB <= numMovies; movieB++) {
            const ratersB = movieRaters[movieB];
            let left = 0;
            let right = 0;
            let dot = 0;
            let normA = 0;
            let normB = 0;
            let count = 0;
            while (left < ratersA.length && right < ratersB.length) {
                const userA = ratersA[left];
                const userB = ratersB[right];
                if (userA === userB) {
                    const ratingA = ratingsMatrix[userA][movieA];
                    const ratingB = ratingsMatrix[userB][movieB];
                    dot += ratingA * ratingB;
                    normA += ratingA ** 2;
                    normB += ratingB ** 2;
                    count++;
                    left++;
                    right++;
                } else if (userA < userB) {
                    left++;
                } else {
                    right++;
                }
            }
            const raw = cosine(dot, normA, normB);
            const weighted = raw * Math.min(count / OVERLAP_THRESHOLD, 1);
            const ab = movieA * itemStride + movieB;
            const ba = movieB * itemStride + movieA;
            itemRaw[ab] = itemRaw[ba] = raw;
            itemWeighted[ab] = itemWeighted[ba] = weighted;
        }
    }

    return { userCommon, userRaw, userWeighted, userRatedMovies, itemRaw, itemWeighted };
}

function cosine(dot, normA, normB) {
    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    if (denominator === 0) return 0;
    return Math.max(0, Math.min(1, dot / denominator));
}

function selectNeighbors(userId, simMatrix, commonMatrix, numUsers) {
    const stride = numUsers + 1;
    const neighbors = [];
    for (let otherId = 1; otherId <= numUsers; otherId++) {
        if (otherId === userId) continue;
        const similarity = simMatrix[userId * stride + otherId];
        if (similarity > 0) {
            neighbors.push({
                userId: otherId,
                similarity,
                commonMovies: commonMatrix[userId * stride + otherId]
            });
        }
    }
    neighbors.sort((a, b) => b.similarity - a.similarity || a.userId - b.userId);
    return neighbors.slice(0, 20);
}

function computeUserStages(data, similarityData) {
    const rawNeighbors = Array(data.numUsers + 1);
    const weightedNeighbors = Array(data.numUsers + 1);
    for (let userId = 1; userId <= data.numUsers; userId++) {
        rawNeighbors[userId] = selectNeighbors(
            userId, similarityData.userRaw, similarityData.userCommon, data.numUsers
        );
        weightedNeighbors[userId] = selectNeighbors(
            userId, similarityData.userWeighted, similarityData.userCommon, data.numUsers
        );
    }

    return {
        rawSupport1: userRecommendationsStage(data, rawNeighbors, 1, false),
        weightedSupport1: userRecommendationsStage(data, weightedNeighbors, 1, false),
        weightedSupport3Before: userRecommendationsStage(data, weightedNeighbors, 3, false),
        weightedSupport3After: userRecommendationsStage(data, weightedNeighbors, 3, true),
        rawNeighbors,
        weightedNeighbors
    };
}

function userRecommendationsStage(data, selectedNeighbors, minSupport, protectAliases) {
    let allFiveScores = 0;
    let emptyLists = 0;
    let shortLists = 0;
    let majorityLowOverlap = 0;
    let duplicateRecommendations = 0;
    let usersWithDuplicateRecommendations = 0;
    const listLengths = Array(6).fill(0);
    const topByUser = Array(data.numUsers + 1);

    for (let userId = 1; userId <= data.numUsers; userId++) {
        const neighbors = selectedNeighbors[userId];
        if (neighbors.length > 0) {
            const lowCount = neighbors.filter(neighbor => neighbor.commonMovies <= 2).length;
            if (lowCount > neighbors.length / 2) majorityLowOverlap++;
        }

        const seenKeys = ratedTitleKeys(data, userId);
        const numerator = new Float64Array(data.numMovies + 1);
        const denominator = new Float64Array(data.numMovies + 1);
        const support = new Uint16Array(data.numMovies + 1);
        for (const neighbor of neighbors) {
            for (const movieId of data.users[neighbor.userId].map(rating => rating.itemId)) {
                if (data.ratingsMatrix[userId][movieId] !== 0) continue;
                numerator[movieId] += neighbor.similarity * data.ratingsMatrix[neighbor.userId][movieId];
                denominator[movieId] += neighbor.similarity;
                support[movieId]++;
            }
        }

        const candidates = [];
        for (let movieId = 1; movieId <= data.numMovies; movieId++) {
            if (data.ratingsMatrix[userId][movieId] !== 0 || denominator[movieId] === 0 ||
                support[movieId] < minSupport) continue;
            const key = titleKey(data.titles[movieId]);
            if (protectAliases && seenKeys.has(key)) continue;
            candidates.push({ movieId, title: data.titles[movieId], score: numerator[movieId] / denominator[movieId] });
        }
        candidates.sort((a, b) => b.score - a.score || a.movieId - b.movieId);
        const list = protectAliases
            ? uniqueByTitle(candidates, seenKeys).slice(0, 5)
            : candidates.slice(0, 5);
        topByUser[userId] = list;
        listLengths[list.length]++;
        if (list.length === 0) emptyLists++;
        if (list.length < 5) shortLists++;
        if (list.length === 5 && list.every(item => item.score.toFixed(3) === '5.000')) allFiveScores++;
        const conflicts = list.filter(item => seenKeys.has(titleKey(item.title))).length;
        duplicateRecommendations += conflicts;
        if (conflicts > 0) usersWithDuplicateRecommendations++;
    }

    return {
        minSupport,
        protectAliases,
        allFiveScores,
        emptyLists,
        shortLists,
        majorityLowOverlap,
        listLengths,
        duplicateRecommendations,
        usersWithDuplicateRecommendations,
        topByUser
    };
}

function computeItemStages(data, similarityData) {
    let rawDuplicateRecommendations = 0;
    let weightedSupport1DuplicateRecommendations = 0;
    let weightedSupport3BeforeDuplicateFix = 0;
    let weightedSupport3AfterDuplicateFix = 0;
    let rawAffectedUsers = 0;
    let weightedSupport1AffectedUsers = 0;
    let weightedSupport3AffectedUsers = 0;
    const topByUser = {
        rawSupport1: Array(data.numUsers + 1),
        weightedSupport1: Array(data.numUsers + 1),
        weightedSupport3Before: Array(data.numUsers + 1),
        weightedSupport3After: Array(data.numUsers + 1)
    };
    let emptyFinalLists = 0;
    let shortFinalLists = 0;

    for (let userId = 1; userId <= data.numUsers; userId++) {
        const ratedMovieIds = data.users[userId].map(rating => rating.itemId).sort((a, b) => a - b);
        const seenKeys = ratedTitleKeys(data, userId);
        const numeratorRaw = new Float64Array(data.numMovies + 1);
        const denominatorRaw = new Float64Array(data.numMovies + 1);
        const numeratorWeighted = new Float64Array(data.numMovies + 1);
        const denominatorWeighted = new Float64Array(data.numMovies + 1);
        const itemStride = data.numMovies + 1;

        for (const ratedMovieId of ratedMovieIds) {
            const activeRating = data.ratingsMatrix[userId][ratedMovieId];
            const rawOffset = ratedMovieId * itemStride;
            for (let candidateId = 1; candidateId <= data.numMovies; candidateId++) {
                if (data.ratingsMatrix[userId][candidateId] !== 0) continue;
                const rawSimilarity = similarityData.itemRaw[rawOffset + candidateId];
                const weightedSimilarity = similarityData.itemWeighted[rawOffset + candidateId];
                numeratorRaw[candidateId] += rawSimilarity * activeRating;
                denominatorRaw[candidateId] += rawSimilarity;
                numeratorWeighted[candidateId] += weightedSimilarity * activeRating;
                denominatorWeighted[candidateId] += weightedSimilarity;
            }
        }

        const scoredRaw = [];
        const scoredWeighted = [];
        for (let candidateId = 1; candidateId <= data.numMovies; candidateId++) {
            if (data.ratingsMatrix[userId][candidateId] !== 0) continue;
            const coRaterSupport = data.movieRaters[candidateId].reduce(
                (count, coRaterId) => count + (similarityData.userCommon[userId * (data.numUsers + 1) + coRaterId] > 0 ? 1 : 0),
                0
            );
            const candidate = { movieId: candidateId, title: data.titles[candidateId], coRaterSupport };
            if (denominatorRaw[candidateId] > 0 && coRaterSupport >= 1) {
                scoredRaw.push({ ...candidate, score: numeratorRaw[candidateId] / denominatorRaw[candidateId] });
            }
            if (denominatorWeighted[candidateId] > 0 && coRaterSupport >= 1) {
                scoredWeighted.push({ ...candidate, score: numeratorWeighted[candidateId] / denominatorWeighted[candidateId] });
            }
        }
        scoredRaw.sort((a, b) => b.score - a.score || a.movieId - b.movieId);
        scoredWeighted.sort((a, b) => b.score - a.score || a.movieId - b.movieId);

        const rawTop = scoredRaw.slice(0, 5);
        const weightedOneTop = scoredWeighted.slice(0, 5);
        const weightedThreeBefore = scoredWeighted.filter(item => item.coRaterSupport >= MIN_ITEM_SUPPORT).slice(0, 5);
        const weightedThreeAfter = uniqueByTitle(
            scoredWeighted.filter(item => item.coRaterSupport >= MIN_ITEM_SUPPORT && !seenKeys.has(titleKey(item.title))),
            seenKeys
        ).slice(0, 5);

        rawDuplicateRecommendations += countTitleConflicts(rawTop, seenKeys);
        weightedSupport1DuplicateRecommendations += countTitleConflicts(weightedOneTop, seenKeys);
        const beforeConflicts = countTitleConflicts(weightedThreeBefore, seenKeys);
        weightedSupport3BeforeDuplicateFix += beforeConflicts;
        weightedSupport3AfterDuplicateFix += countTitleConflicts(weightedThreeAfter, seenKeys);
        if (countTitleConflicts(rawTop, seenKeys)) rawAffectedUsers++;
        if (countTitleConflicts(weightedOneTop, seenKeys)) weightedSupport1AffectedUsers++;
        if (beforeConflicts) weightedSupport3AffectedUsers++;
        if (weightedThreeAfter.length === 0) emptyFinalLists++;
        if (weightedThreeAfter.length < 5) shortFinalLists++;

        if ([1, 196].includes(userId)) {
            topByUser.rawSupport1[userId] = rawTop;
            topByUser.weightedSupport1[userId] = weightedOneTop;
            topByUser.weightedSupport3Before[userId] = weightedThreeBefore;
            topByUser.weightedSupport3After[userId] = weightedThreeAfter;
        }
    }

    return {
        rawDuplicateRecommendations,
        weightedSupport1DuplicateRecommendations,
        weightedSupport3BeforeDuplicateFix,
        weightedSupport3AfterDuplicateFix,
        rawAffectedUsers,
        weightedSupport1AffectedUsers,
        weightedSupport3AffectedUsers,
        emptyFinalLists,
        shortFinalLists,
        topByUser
    };
}

function ratedTitleKeys(data, userId) {
    return new Set(data.users[userId].map(rating => titleKey(data.titles[rating.itemId])));
}

function titleKey(title) {
    return title.normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
}

function uniqueByTitle(candidates, initiallySeenKeys) {
    const seen = new Set(initiallySeenKeys);
    const unique = [];
    for (const candidate of candidates) {
        const key = titleKey(candidate.title);
        if (seen.has(key)) continue;
        seen.add(key);
        unique.push(candidate);
    }
    return unique;
}

function countTitleConflicts(recommendations, seenKeys) {
    return recommendations.filter(item => seenKeys.has(titleKey(item.title))).length;
}

function computeManualCalculation(data, userStages) {
    const neighbor = userStages.weightedNeighbors[1][0];
    const userId = 1;
    const active = data.ratingsMatrix[userId];
    let dot = 0;
    let normActive = 0;
    let normNeighbor = 0;
    const common = [];
    for (let movieId = 1; movieId <= data.numMovies; movieId++) {
        const activeRating = active[movieId];
        const neighborRating = data.ratingsMatrix[neighbor.userId][movieId];
        if (activeRating === 0 || neighborRating === 0) continue;
        dot += activeRating * neighborRating;
        normActive += activeRating ** 2;
        normNeighbor += neighborRating ** 2;
        common.push({
            movieId,
            title: data.titles[movieId],
            activeRating,
            neighborRating
        });
    }
    const raw = cosine(dot, normActive, normNeighbor);
    const overlapWeight = Math.min(common.length / OVERLAP_THRESHOLD, 1);
    const manualSimilarity = raw * overlapWeight;

    const top = userStages.weightedSupport3After.topByUser[1][0];
    const terms = userStages.weightedNeighbors[1]
        .map(item => ({
            userId: item.userId,
            similarity: item.similarity,
            rating: data.ratingsMatrix[item.userId][top.movieId]
        }))
        .filter(item => item.rating !== 0);
    const numerator = terms.reduce((sum, item) => sum + item.similarity * item.rating, 0);
    const denominator = terms.reduce((sum, item) => sum + item.similarity, 0);

    return {
        userId,
        neighborId: neighbor.userId,
        commonRatings: common,
        dot,
        normActive,
        normNeighbor,
        rawCosine: raw,
        overlapWeight,
        manualSimilarity,
        codeSimilarity: neighbor.similarity,
        recommendation: top,
        terms,
        numerator,
        denominator,
        manualPrediction: numerator / denominator,
        codePrediction: top.score
    };
}

async function runWeek2Genre(week2Dir, activeUserId) {
    const [dataSource, scriptSource] = await Promise.all([
        fs.readFile(path.join(week2Dir, 'data.js'), 'utf8'),
        fs.readFile(path.join(week2Dir, 'script.js'), 'utf8')
    ]);
    const context = createBrowserContext(week2Dir);
    const output = await vm.runInContext(`
        ${dataSource}
        ${scriptSource}
        (async () => {
            await loadData();
            const topRated = ratings
                .filter(rating => rating.userId === ${activeUserId})
                .sort((a, b) => b.rating - a.rating ||
                    movies.find(movie => movie.id === a.itemId).title.localeCompare(
                        movies.find(movie => movie.id === b.itemId).title
                    ) || a.itemId - b.itemId)
                .slice(0, 3);
            const seeds = topRated.map(rating => ({
                ...movies.find(movie => movie.id === rating.itemId),
                userRating: rating.rating
            }));
            const toyStoryGenres = movies.find(movie => movie.id === 1).genres;
            return {
                numMovies: movies.length,
                numRatings: ratings.length,
                seeds,
                toyStoryGenres,
                top5: getTopRecommendations(seeds, 5).map(({ id, title, score, popularity }) => ({
                    movieId: id, title, score, popularity
                }))
            };
        })()
    `, context);
    return JSON.parse(JSON.stringify(output));
}

async function runWeek3Cf(fixedDir, userId) {
    const [dataSource, scriptSource] = await Promise.all([
        fs.readFile(path.join(fixedDir, 'data.js'), 'utf8'),
        fs.readFile(path.join(fixedDir, 'script.js'), 'utf8')
    ]);
    const context = createBrowserContext(fixedDir);
    const output = await vm.runInContext(`
        ${dataSource}
        ${scriptSource}
        (async () => {
            await loadData();
            return {
                userId: ${userId},
                numMovies: movies.length,
                numRatings: ratings.length,
                userBasedTop5: getUserBasedRecommendations(${userId}, 5),
                itemBasedTop5: getItemBasedRecommendations(${userId}, 5)
            };
        })()
    `, context);
    return JSON.parse(JSON.stringify(output));
}

function createBrowserContext(dataDir) {
    return vm.createContext({
        console,
        TextDecoder,
        window: {},
        document: { getElementById: () => null },
        fetch: async fileName => {
            const buffer = await fs.readFile(path.join(dataDir, fileName));
            return {
                ok: true,
                text: async () => buffer.toString('utf8'),
                arrayBuffer: async () => buffer.buffer.slice(
                    buffer.byteOffset,
                    buffer.byteOffset + buffer.byteLength
                )
            };
        }
    });
}

function assertRecommendationsMatch(expected, actual, label) {
    assert.equal(expected.length, actual.length, `${label}: result length mismatch`);
    for (let index = 0; index < expected.length; index++) {
        assert.equal(expected[index].title, actual[index].title, `${label}: title at rank ${index + 1}`);
        assert.ok(Math.abs(expected[index].score - actual[index].score) < 1e-10,
            `${label}: score at rank ${index + 1}`);
    }
}

function assertItemBasedRegressionListsUnchanged(actualResults) {
    const expected = {
        1: [
            ['A Chef in Love (1996)', '4.068'],
            ['Rendezvous in Paris (Rendez-vous de Paris, Les) (1995)', '4.047'],
            ['Last Summer in the Hamptons (1995)', '4.041'],
            ['Bitter Sugar (Azucar Amargo) (1996)', '4.038'],
            ['Wonderful, Horrible Life of Leni Riefenstahl, The (1993)', '4.029']
        ],
        196: [
            ['Stonewall (1995)', '3.904'],
            ['Innocents, The (1961)', '3.894'],
            ['Wonderful, Horrible Life of Leni Riefenstahl, The (1993)', '3.892'],
            ['Aparajito (1956)', '3.889'],
            ['The Innocent (1994)', '3.885']
        ]
    };
    for (const [userId, expectedTop5] of Object.entries(expected)) {
        const actual = actualResults.find(result => result.userId === Number(userId)).itemBasedTop5
            .map(item => [item.title, item.score.toFixed(3)]);
        assert.deepEqual(actual, expectedTop5, `Item-Based Top-5 changed for user ${userId}`);
    }
}

function renderBaseline(data, overlap, userStages, itemStages) {
    const raw = userStages.rawSupport1;
    const legacyItemDupes = itemStages.rawDuplicateRecommendations;
    const legacyUserDupes = raw.duplicateRecommendations;
    return [
        '# Baseline before hardening',
        '',
        'The starter in `original/` had TODOs for the rating matrix, cosine similarity, and both CF recommenders, so it could not produce a working CF Top-5 as supplied. For a numerical baseline, this report reconstructs the intended executable version: co-rated-only cosine, no overlap shrinkage, one supporting neighbor/co-rater is enough, and no title-alias guard.',
        '',
        '## Dataset and original data issues',
        '',
        `- ${data.numUsers} users, ${data.numMovies} movies, ${data.ratings.length.toLocaleString('en-US')} ratings; ${((data.ratings.length / data.movieCells) * 100).toFixed(2)}% of matrix cells are rated.`,
        `- The u.item file is ISO-8859-1, but the starter read it as UTF-8 response text. Movie ID 543 was decoded as “${data.legacyUtf8Title}” instead of “${data.titles[543]}”.`,
        '- The genre parser started at the “unknown” flag, shifting every named genre by one position.',
        `- There are ${data.duplicateGroups.length} groups of identical movie titles under different IDs. In ${data.duplicateAliasCases} user/title cases, one ID was rated while another ID for the same title remained unrated.`,
        '',
        '## Reconstructed unfiltered CF baseline',
        '',
        `- With raw co-rated-only cosine, ${raw.allFiveScores}/${data.numUsers} users had every displayed User-Based Top-5 score equal to 5.000.`,
        `- For ${raw.majorityLowOverlap}/${data.numUsers} users, a majority of the selected top-20 neighbors shared at most two movies.`,
        `- Before title-alias filtering, the raw baseline produced ${legacyUserDupes} User-Based and ${legacyItemDupes} Item-Based Top-5 entries whose title matched a movie already rated by that user under another ID.`,
        '',
        'These duplicate counts are recommendation rows, not distinct users. “Before” refers to this reconstructed executable algorithm, not to the literal TODO functions in `original/`.',
        ''
    ].join('\n');
}

function renderStages(data, users, items) {
    const stages = [
        ['Raw co-rated cosine; one supporter', users.rawSupport1],
        ['Overlap-weighted cosine (5); one supporter', users.weightedSupport1],
        ['Overlap-weighted cosine (5); 3 User-Based supporters', users.weightedSupport3Before]
    ];
    const lines = [
        '# Stage comparison',
        '',
        'The first three rows use the same user-neighbor definition (top 20 positive similarities) and differ by overlap weighting and minimum recommendation support. The final alias guard changes candidate eligibility/deduplication only.',
        '',
        '| User-Based stage | All Top-5 scores 5.000 | Majority of neighbors overlap ≤2 | Empty lists | Duplicate-rated title rows |',
        '|---|---:|---:|---:|---:|'
    ];
    for (const [name, result] of stages) {
        lines.push(`| ${name} | ${result.allFiveScores}/${data.numUsers} (${percent(result.allFiveScores, data.numUsers)}) | ${result.majorityLowOverlap}/${data.numUsers} (${percent(result.majorityLowOverlap, data.numUsers)}) | ${result.emptyLists} | ${result.duplicateRecommendations} |`);
    }

    lines.push(
        '',
        '## Duplicate-title recommendations across all users',
        '',
        'The “before title guard” counts use the current overlap and support settings: overlap threshold 5, at least 3 neighbors for User-Based, and at least 3 distinct co-raters for Item-Based. The after run uses the same settings plus title-alias exclusion and title deduplication.',
        '',
        '| CF method | Before: duplicate-rated title rows | Users affected | After |',
        '|---|---:|---:|---:|',
        `| User-Based | ${users.weightedSupport3Before.duplicateRecommendations} | ${users.weightedSupport3Before.usersWithDuplicateRecommendations} | ${users.weightedSupport3After.duplicateRecommendations} |`,
        `| Item-Based | ${items.weightedSupport3BeforeDuplicateFix} | ${items.weightedSupport3AffectedUsers} | ${items.weightedSupport3AfterDuplicateFix} |`,
        '',
        '## Item-Based support filter',
        '',
        `The candidate now needs ${MIN_ITEM_SUPPORT} distinct users who rated it and at least one film from the active user’s history. The rule is applied before Top-5 selection. Under the final rule, empty Item-Based Top-5 lists: ${items.emptyFinalLists}/${data.numUsers}; lists shorter than five: ${items.shortFinalLists}/${data.numUsers}.`,
        '',
        '### Item-Based Top-5 examples before/after the support filter',
        '',
        '| User | Minimum support 1 | Minimum support 3 |',
        '|---:|---|---|'
    );
    for (const userId of [1, 196]) {
        const before = items.topByUser.weightedSupport1[userId];
        const after = items.topByUser.weightedSupport3After[userId];
        lines.push(`| ${userId} | ${before.map(item => `${item.title} (${item.score.toFixed(3)})`).join('; ')} | ${after.map(item => `${item.title} (${item.score.toFixed(3)})`).join('; ')} |`);
    }
    lines.push(
        '',
        'User-Based list lengths after the final support rule (0 through 5): ' + users.weightedSupport3After.listLengths.map((count, length) => `${length}: ${count}`).join(', ') + '.',
        ''
    );
    return lines.join('\n');
}

function renderAnalytics(data, overlap, genre, cf) {
    const userRatedCount = data.users[1].length;
    const userBasedCoordinates = (data.numUsers - 1) * (data.numMovies + 1);
    const itemBasedCoordinates = userRatedCount * (data.numMovies - userRatedCount) * data.numUsers;
    const userPairs = data.numUsers * (data.numUsers - 1) / 2;
    const itemPairs = data.numMovies * (data.numMovies - 1) / 2;
    const userAllPairOps = userPairs * data.numMovies;
    const itemAllPairOps = itemPairs * data.numUsers;
    const seedNames = genre.seeds.map(movie => `${movie.title} (${movie.userRating})`).join('; ');
    const lines = [
        '# Analytics',
        '',
        '## User-Based vs Item-Based: quality and speed',
        '',
        'Neither method is universally more accurate. Compare quality offline by hiding known ratings and measuring Recall@5/NDCG@5. User-Based finds similar people; Item-Based finds co-rated films and can precompute/cache film similarities. Item-Based often scales better when there are many more users than items; User-Based can be cheaper when items outnumber users.',
        '',
        `This dataset has ${data.numUsers} users and ${data.numMovies} movies. A dense full-pair build is approximately ${userPairs.toLocaleString('en-US')} user pairs × ${data.numMovies} movies = ${userAllPairOps.toLocaleString('en-US')} coordinates for User-Based, versus ${itemPairs.toLocaleString('en-US')} movie pairs × ${data.numUsers} users = ${itemAllPairOps.toLocaleString('en-US')} for Item-Based (${(itemAllPairOps / userAllPairOps).toFixed(2)}× more).`,
        '',
        `For one query in this implementation, user 1 has ${userRatedCount} ratings: User-Based scans about ${userBasedCoordinates.toLocaleString('en-US')} vector positions; on-the-fly Item-Based scans about ${itemBasedCoordinates.toLocaleString('en-US')} (${(itemBasedCoordinates / userBasedCoordinates).toFixed(1)}×). Precomputing the item matrix trades preprocessing/storage for faster requests. These are operation estimates, not measured wall-clock times.`,
        '',
        '## Missing-value strategies',
        '',
        '| Strategy | Hand-calculated similarity | Simplicity, bias, and cost |',
        '|---|---:|---|',
        '| Ignore missing values; compare co-rated entries | 1.000 | Simplest and does not invent ratings; one shared positive rating can falsely look perfect. Sparse intersections are cheap. |',
        '| Fill missing values with user means | 0.886 | Dense vectors, but imputed values can create artificial agreement/disagreement and bias results toward averages. |',
        '| Weight by overlap count; threshold 5 | 0.200 for one shared rating | Adds a small overlap-count/weight step and suppresses weak evidence; threshold tuning may disadvantage sparse users/items. |',
        '',
        'Example: A=(5,1,missing), B=(5,missing,1). Co-rated-only compares [5] with [5], cosine 1. Row-mean imputation gives A=(5,1,3), B=(5,3,1): dot=31, squared norms=35 each, cosine=31/35≈0.886. Overlap weighting scales the one-common-item cosine by 1/5=0.2. Mean imputation requires a choice of user/item mean and may create relationships absent from the data.',
        '',
        '## Cold start and sparsity',
        '',
        `The matrix has ${data.movieCells.toLocaleString('en-US')} possible cells and ${data.ratings.length.toLocaleString('en-US')} observed ratings (${(data.ratings.length / data.movieCells * 100).toFixed(2)}% density). New users have no history for neighbors or an item profile; new movies have no co-ratings. Use content/genre recommendations or onboarding until interactions arrive.`,
        '',
        `Across all ${overlap.pairs.toLocaleString('en-US')} unordered pairs of distinct users, median shared films = **${overlap.median}**; pairs sharing at most two films = **${overlap.atMostTwo.toLocaleString('en-US')} (${overlap.atMostTwoPercent.toFixed(2)}%)**. Median 10 checks out; “about 13%” is somewhat below the measured 14.29%. ${overlap.noCommon.toLocaleString('en-US')} pairs have no shared ratings. Cosine on one common positive rating is always 1, so small overlap is weak evidence.`,
        '',
        '## Same-user Top-5: genre-based vs CF',
        '',
        `Week 2 asks for up to three liked movies, not a user ID. For a reproducible same-user comparison, I selected user 1’s three highest-rated movies (ties by title, then ID): ${seedNames}. CF uses all of user 1’s ratings.`,
        '',
        '| Rank | Genre-based (genre cosine) | User-Based CF (predicted rating) | Item-Based CF (predicted rating) |',
        '|---:|---|---|---|'
    ];
    for (let rank = 0; rank < 5; rank++) {
        lines.push(`| ${rank + 1} | ${formatTop(genre.top5[rank], true)} | ${formatTop(cf.userBasedTop5[rank], false)} | ${formatTop(cf.itemBasedTop5[rank], false)} |`);
    }
    lines.push(
        '',
        'Genre-based recommendations match the selected films’ metadata. CF follows audience rating patterns, so it can cross genre boundaries. Scores have different meanings and are not directly comparable; a single user’s list does not establish which method has better quality.',
        ''
    );
    return lines.join('\n');
}

function renderChecks(data, genre, manual, userStages, itemStages) {
    const lines = [
        '# Checks and manual formula verification',
        '',
        '## Data parsing and duplicate-title safety',
        '',
        `- ISO-8859-1 decoding: movie ID 543 is “${data.titles[543]}”; the old UTF-8 decode was “${data.legacyUtf8Title}”; replacement-character titles after the fix: ${data.replacementTitleCount}.`,
        `- Genre offset: movie ID 1 (Toy Story) parses as ${genre.toyStoryGenres.join(', ')}. The old offset would have reported ${data.legacyToyStoryGenres.join(', ')}.`,
        `- Exact normalized duplicate-title groups: ${data.duplicateGroups.length}; user/title cases with one duplicate ID rated and another unrated: ${data.duplicateAliasCases}.`,
        `- Duplicate-rated Top-5 rows before alias guard (current other policies): User-Based ${userStages.weightedSupport3Before.duplicateRecommendations}; Item-Based ${itemStages.weightedSupport3BeforeDuplicateFix}. After guard: User-Based ${userStages.weightedSupport3After.duplicateRecommendations}; Item-Based ${itemStages.weightedSupport3AfterDuplicateFix}.`,
        '- Final recommendation lists for users 1 and 196 match the actual fixed JavaScript methods; a full-dataset optimized calculation confirms zero duplicate-rated title rows after the guard.',
        '- Simplifying the Item-Based support count left the Top-5 title/score pairs unchanged for users 1 and 196.',
        '',
        '## Manual cosine calculation',
        '',
        `User ${manual.userId} vs user ${manual.neighborId}; common ratings in order: ${manual.commonRatings.map(row => `${row.title} ${row.activeRating}×${row.neighborRating}`).join('; ')}.`,
        `- n=${manual.commonRatings.length}; dot=${manual.dot}; squared norms=${manual.normActive} and ${manual.normNeighbor}.`,
        `- Raw cosine = ${manual.dot}/(√${manual.normActive} × √${manual.normNeighbor}) = ${manual.rawCosine.toFixed(9)}; overlap weight = ${manual.overlapWeight.toFixed(3)}.`,
        `- Adjusted similarity manually = ${manual.manualSimilarity.toFixed(9)}; fixed code = ${manual.codeSimilarity.toFixed(9)}.`,
        '',
        '## Manual User-Based prediction',
        '',
        `For ${manual.recommendation.title}, contributing neighbors: ${manual.terms.map(term => `${term.userId}: ${term.similarity.toFixed(6)}×${term.rating}`).join('; ')}.`,
        `- Weighted sum = ${manual.numerator.toFixed(9)}; similarity sum = ${manual.denominator.toFixed(9)}.`,
        `- Prediction = ${manual.numerator.toFixed(9)}/${manual.denominator.toFixed(9)} = ${manual.manualPrediction.toFixed(9)}; code = ${manual.codePrediction.toFixed(9)}.`,
        '',
        'The script asserts agreement between manual and code values (tolerance 1e-12) and between optimized all-user rankings and the actual fixed recommenders for users 1 and 196.',
        ''
    ];
    return lines.join('\n');
}

function percent(count, total) {
    return `${(count / total * 100).toFixed(2)}%`;
}

function formatTop(item, isGenre) {
    if (!item) return '—';
    return `${item.title} (${item.score.toFixed(3)})`;
}
